package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_isNumber_TriageGen1Test {









    @Test
    public void testIsNumber_Exponents() {
        assertTrue(NumberUtils.isNumber("123e10"));
        assertTrue(NumberUtils.isNumber("123E10"));
        assertTrue(NumberUtils.isNumber("123e-10"));
        assertTrue(NumberUtils.isNumber("123E+10"));
        assertTrue(NumberUtils.isNumber("-123e10"));
        assertTrue(NumberUtils.isNumber("1.23e10"));

        assertFalse(NumberUtils.isNumber("e10"));
        assertFalse(NumberUtils.isNumber("123e"));
        assertFalse(NumberUtils.isNumber("123e10e10"));
        assertFalse(NumberUtils.isNumber("123e1.23")); // decimal in exponent not allowed via current logic
        assertFalse(NumberUtils.isNumber("123e+-10"));
    }






}

package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_isNumber_TriageGen1Test {











    @Test
    public void testIsNumber_TypeQualifiers() {
        // d, D, f, F
        assertTrue(NumberUtils.isNumber("123d"));
        assertTrue(NumberUtils.isNumber("123D"));
        assertTrue(NumberUtils.isNumber("123f"));
        assertTrue(NumberUtils.isNumber("123F"));
        assertTrue(NumberUtils.isNumber("123.45f"));

        // l, L
        assertTrue(NumberUtils.isNumber("123l"));
        assertTrue(NumberUtils.isNumber("123L"));

        // Invalid qualifiers
        assertFalse(NumberUtils.isNumber("123eL")); // L not allowed with exponent
        assertFalse(NumberUtils.isNumber("123.45L")); // L not allowed with decimal
        assertFalse(NumberUtils.isNumber("123z"));
    }




}

package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_isNumber_TriageGen1Test {













    @Test
    public void testIsNumber_EdgeCases() {
        // Test combinations of logic for branch coverage
        assertFalse(NumberUtils.isNumber("1E-"));
        assertFalse(NumberUtils.isNumber("1E+"));

        // Test the while loop condition (i < sz + 1 && allowSigns && !foundDigit)
        // This typically triggers when a sign follows an 'E' but no digits have been found yet
        assertFalse(NumberUtils.isNumber("1E-")); 

        // Test trailing characters
        assertFalse(NumberUtils.isNumber("123a"));
        assertTrue(NumberUtils.isNumber("123"));

        // Test dot logic
        assertTrue(NumberUtils.isNumber("1."));
        assertFalse(NumberUtils.isNumber(".")); // foundDigit is false
    }


}

package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_isNumber_TriageGen1Test {















    @Test
    public void testIsNumber_ComplexSignLogic() {
        assertTrue(NumberUtils.isNumber("-123"));
        assertTrue(NumberUtils.isNumber("123+456")); // This should be false based on logic
        assertFalse(NumberUtils.isNumber("123+456"));

        // Test sign at start of exponent
        assertTrue(NumberUtils.isNumber("1e+1"));
        assertTrue(NumberUtils.isNumber("1e-1"));
    }
}
